const origin='https://degreepath.example',alice={id:'sb-11111111-1111-4111-8111-111111111111',email:'alice@example.com'},bob={id:'sb-22222222-2222-4222-8222-222222222222',email:'bob@example.com'},owner={id:'sb-33333333-3333-4333-8333-333333333333',email:'owner@example.com'};
