function fixture(t,extra={}){const sqlite=new DatabaseSync(':memory:');sqlite.exec(readFileSync(new URL('../db/schema.sql',import.meta.url),'utf8'));sqlite.exec(readFileSync(new URL('../drizzle/0005_reviewed_templates.sql',import.meta.url),'utf8'));sqlite.exec(readFileSync(new URL('../drizzle/0007_research_progress.sql',import.meta.url),'utf8'));t.after(()=>sqlite.close());const queries=[],DB={prepare(sql){queries.push(sql);assert.doesNotMatch(sql,/\b(?:CREATE|ALTER|DROP)\b/i);const p=sqlite.prepare(sql);return{bind(...args){return{first:()=>p.get(...args)||null,all:()=>({results:p.all(...args)}),run:()=>({meta:{changes:Number(p.run(...args).changes)}})}}}}};DB.batch=async statements=>{sqlite.exec('BEGIN');try{const results=statements.map(s=>s.run());sqlite.exec('COMMIT');return results;}catch(error){sqlite.exec('ROLLBACK');throw error;}};const env={DB,COMMUNITY_ADMIN_EMAIL:owner.email,TEMPLATE_VALIDATE_ACADEMICS:artifact=>validateAcademicTemplate(artifact,{Planner}),...extra};async function call(path,{method='GET',user=alice,body,headers={}}={}){const h={...(method==='GET'?{}:{Origin:origin,'X-Portal-Request':'1','Content-Type':'application/json'}),...headers};const r=await handleTemplateResearch(new Request(origin+path,{method,headers:h,...(body?{body:JSON.stringify(body)}:{})}),{...env,PORTAL_USER:user},{});return{status:r.status,body:await r.json()};}return{sqlite,env,call,queries};}
function artifact(){
 const scope={schoolName:target.schoolName,programName:target.programName,level:target.level,modality:target.modality,catalogYear:target.catalogYear};
 const a={...scope,officialUniversityUrl:'https://catalog.example.edu/business/',creditSystem:'semester',totalCredits:12,institutionMinCredits:3,externalMaxCredits:9,upperMinCredits:3,majorInstitutionFraction:.25,majorResidencyBasisCredits:6,policySourceIds:['policies'],requirements:[1,2,3,4].map(n=>({id:'course-'+n,code:'BUSI '+(n===4?'401':'10'+n),title:'Named course '+n,section:n>2?'major':'general',credits:3,requiredAtUniversity:n===4,upper:n===4,prerequisites:[],sourceIds:['catalog'],options:[{id:'university-'+n,provider:'University',code:'BUSI '+(n===4?'401':'10'+n),title:'Named course '+n,credits:3,creditSystem:'semester',upper:n===4,sourceIds:['catalog'],url:'https://catalog.example.edu/course-'+n+'/',evidence:'published'}]})),sources:[{id:'catalog',url:'https://catalog.example.edu/business/',title:'Published degree',kind:'university',roles:['curriculum'],scope,checked:'2026-11-16'},{id:'policies',url:'https://catalog.example.edu/policies/',title:'Published transfer policies',kind:'university',roles:['policy'],scope,checked:'2026-11-16'}],pros:[{text:'Published transfer options exist.',sourceIds:['policies']}],cons:[{text:'A university minimum remains.',sourceIds:['policies']}],unresolved:[]};
 a.policyEvidence=Object.fromEntries(['institutionMinCredits','externalMaxCredits','upperMinCredits','majorInstitutionFraction','majorResidencyBasisCredits'].map(field=>[field,{value:a[field],sourceIds:['policies']}]));return a;
}
function fetchResult(url,{data='Synthetic complete public curriculum fixture.',sourceType='text',mediaType='text/plain'}={}){return{type:'web_fetch_tool_result',tool_use_id:'srvtoolu-fixture',content:{type:'web_fetch_result',url,content:{type:'document',source:{type:sourceType,media_type:mediaType,data},title:'Official degree source fixture',citations:{enabled:true}},retrieved_at:'2026-11-17T00:00:00Z'}};}
function vendor(result=artifact()){const curriculum=result.sources.find(source=>source.kind==='university'&&source.roles?.includes('curriculum'));return new Response(JSON.stringify({stop_reason:'end_turn',usage:{input_tokens:100,output_tokens:200},content:[{type:'web_search_tool_result',content:result.sources.map(s=>({type:'web_search_result',url:s.url,title:s.title}))},...(curriculum?[fetchResult(curriculum.url)]:[]),{type:'text',text:JSON.stringify(result)}]}),{headers:{'Content-Type':'application/json'}});}
async function request(f,overrides={},user=alice){return f.call('/api/templates/requests',{method:'POST',user,body:{...target,...overrides}});}

