function seedReady(f,n,value=artifact(),stamp=Date.now()){
 const id='tpl-'+n.toString(16).padStart(32,'0');
 f.sqlite.prepare("INSERT INTO degree_templates (id,canonical_key,school_name,program_name,level,modality,catalog_year,status,artifact_json,unresolved_json,revision,sources_reviewed,academic_reviewed,checked_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,'ready',?,'[]',1,1,1,?,?,?)").run(id,'public-read-'+n,target.schoolName,target.programName,target.level,target.modality,target.catalogYear,JSON.stringify(value),stamp,stamp,stamp);
 return id;
}
