 let calls=0;const f=fixture(t,{TEMPLATE_RESEARCH_FETCH:async()=>{calls++;throw new Error('Public reads must never research.');}}),valid=seedReady(f,1),broken=artifact();broken.requirements.pop();const invalid=seedReady(f,2,broken),academic=artifact();academic.summary='Current academic rejection fixture';const rejected=seedReady(f,3,academic),original=f.env.TEMPLATE_VALIDATE_ACADEMICS;
 f.env.TEMPLATE_VALIDATE_ACADEMICS=(value,row)=>value.summary===academic.summary?{valid:false,issues:['Current rule blocks this saved plan.']}:original(value,row);
 const list=await f.call('/api/templates',{user:null});assert.equal(list.status,200);assert.deepEqual(list.body.items.map(item=>item.id),[valid]);assert.equal(list.body.nextCursor,null);assert.equal((await f.call('/api/templates/'+valid,{user:null})).status,200);
