async function streamResponse(f,{path='/api/templates/requests',user=alice,body={url:target.url,startResearch:true},ctx={}}={}){return handleTemplateResearch(new Request(origin+path,{method:'POST',headers:{Origin:origin,'X-Portal-Request':'1','Content-Type':'application/json',Accept:'text/event-stream'},body:JSON.stringify(body)}),{...f.env,PORTAL_USER:user},ctx);}
async function remainingStream(reader){let text='';const decoder=new TextDecoder();while(true){const {done,value}=await reader.read();if(done)return text+decoder.decode();text+=decoder.decode(value,{stream:true});}}
function streamEvents(value){return value.split('\n\n').filter(frame=>frame.startsWith('event: ')).map(frame=>({event:frame.split('\n')[0].slice(7),data:JSON.parse(frame.split('\ndata: ')[1])}));}

