 let sent;const registry=buildCreditSourceDiscovery(discoveryDirectory()),a=artifact();a.providerDiscovery={domains:['untrusted-model.example.edu'],hints:'MODEL DIRECTORY'};const f=fixture(t,{ANTHROPIC_API_KEY:'test-server-key-only',TEMPLATE_CREDIT_SOURCES:registry,TEMPLATE_RESEARCH_FETCH:async(url,options)=>{sent=JSON.parse(options.body);return vendor(a);}});assert.equal((await linkRequest(f,target.url,alice,{TEMPLATE_CREDIT_SOURCES:{domains:['untrusted-student.example.edu']}})).status,400);assert.equal((await linkRequest(f)).body.template.qualityReady,true);assert(!sent.tools.find(tool=>tool.name==='web_fetch').allowed_domains.includes('untrusted-model.example.edu'));assert.doesNotMatch(sent.messages[0].content,/untrusted-student|MODEL DIRECTORY/);
